    "DirectX & OpenGL Switch (-Y/+Y)": "التبديل بين تنسيق DirectX وOpenGL (-Y/+Y)",
    "Live 3D PBR Preview Sphere": "كرة فحص خامات PBR ثلاثية الأبعاد تفاعلية",
    "Scan to project 3D models at true real-world scale directly into your physical room.": "امسح الرمز بكاميرا هاتفك لمعاينة المجسم في غرفتك بالأبعاد الحقيقية 1:1 عبر الواقع المعزز.",
    "Live inspection of triangles, vertex density, materials, and clean quad topology.": "فحص فوري ودقيق للمثلثات وكثافة الرؤوس وسلامة التوبولوجي وتوزيع الخامات في الوقت الفعلي.",
    "Generate one-click studio renders with transparent alpha backgrounds instantly.": "التقط صور ريندر احترافية بضغطة زر واحدة مع خلفية شفافة نقية ومفرغة جاهزة للاستخدام.",
    "Switch between studio neutral, warm interior, and high-contrast outdoor presets.": "تنقل بسهولة بين إضاءة الاستوديو الحيادية، والإضاءة الداخلية الدافئة، وإضاءات البيئة الخارجية المتباينة.",
    "Package loose .gltf, .bin buffers, and image textures into 1 self-contained GLB.": "تجميع ملفات GLTF المنفصلة وملفات الباينري والخامات في ملف GLB واحد متكامل ومضغوط.",
    "Deconstruct binary GLB archives into editable loose texture maps and mesh buffers.": "فك ضغط ملفات الـ GLB واستخراج الخامات والصور ومصفوفات المجسمات لتعديلها بسهولة.",
    "Re-encode heavy PNG textures to reduce binary GLB size by 70% to 80% losslessly.": "إعادة ترميز خامات PNG الثقيلة لتقليل حجم ملف الـ GLB بنسبة 70% إلى 80% مع الحفاظ على أعلى جودة.",
    "Automated schema check for missing textures, corrupt nodes, and UV errors.": "فحص برمجي تلقائي للتحقق من عدم وجود خامات مفقودة أو عقد تالفة أو أخطاء في الـ UV.",
    "Transform grayscale displacement maps or color textures into tangent-space normals.": "تحويل خرائط الإزاحة التدرجية أو الصور الملونة إلى خرائط نورمال دقيقة في فضاء المماس.",
    "Mathematical convolution operators for fine micro-surface details or deep bevels.": "خوارزميات التواء رياضية متقدمة لإبراز التفاصيل السطحية الدقيقة أو الحواف المشطوفة العميقة.",
    "Invert green channel for seamless compatibility with Unreal Engine, Blender, and Unity.": "عكس القناة الخضراء (Green Channel) للتوافق التام مع Unreal Engine وBlender وUnity.",
    "Interactive 3D material ball with orbiting light feedback to evaluate surface relief.": "كرة خامات ثلاثية الأبعاد تفاعلية مع إضاءة مدارية متحركة لتقييم عمق وبروز التفاصيل مباشرة.",
    "Zero cloud uploads. All parsing and encoding runs privately in your local browser RAM.": "بدون رفع أي ملفات للسيرفر. تتم معالجة وتشفير الملفات بالكامل داخل ذاكرة جهازك وبخصوصية مطلقة.",
    "3D & AR Model Viewer": "عارض مجسمات الـ 3D والواقع المعزز (AR)",
    "3D Viewer & Inspector": "أداة فحص ومعاينة الـ 3D المتقدمة",
