    "Marvelous Designer fabric physics, detailed seam micro-displacement, and procedural leather wear.": "محاكاة فيزيائية للأقمشة في Marvelous Designer، وتفاصيل دقيقة لخياطة الحواف، وخامات جلدية واقعية.",
    "Sub-D quad topology, physical dispersion shaders, and high-accuracy glass refraction.": "توبولوجي مضلعات رباعية عالي النعومة، وخامات تشتت فيزيائي، وانكسار ضوئي فائق الدقة للزجاج.",
    "Precision hard-surface modeling, studio calibrated light rig, pure white background (RGB 255).": "نمذجة ميكانيكية دقيقة للأسطح الصلبة، وإضاءة استوديو معايرة، وخلفية بيضاء نقية (RGB 255).",
    "Preserves Base Color, Roughness, Metallic, Normal Maps, Emissive, and Ambient Occlusion channels correctly without loss of color space.": "يحافظ بدقة على قنوات اللون والخشونة والمعدنية والنورمال والتوهج والظلال المحيطية دون أي فقدان لمساحة الألوان.",
    "Reference photos, dimensions/blueprints, sketches, or standard 3D file formats (Blender .blend, OBJ, FBX, GLTF).": "صور مرجعية، أبعاد أو مخططات هندسية، رسومات أولية، أو صيغ ملفات 3D قياسية (.blend, OBJ, FBX, GLTF).",
    "Standard 3x3 convolution with smooth gradient transitions. Ideal for organic fabrics and leather.": "خوارزمية التواء قياسية 3x3 مع تدرجات ناعمة. مثالية للأقمشة الطبيعية والجلود العضوية.",
    "Technical scope, geometry execution, and production deliverables behind selected commercial projects.": "المواصفات التقنية، وتنفيذ الهندسة الشبكية، والتسليمات الإنتاجية وراء مشاريع تجارية مختارة.",
    "Tell me about your product or furniture collection. I will review your requirements and provide a tailored scope, timeline, and quote within 24 hours.": "أخبرني عن منتجك أو مجموعة الأثاث الخاصة بك. سأقوم بمراجعة متطلباتك وتقديم عرض عمل محدد مع التكلفة والجدول الزمني خلال 24 ساعة.",
