    "Mustafa Jamal. All Rights Reserved. Built with 100% Client-Side WebGL Architecture.": "مصطفى جمال. جميع الحقوق محفوظة. تم البناء بهندسة WebGL تعمل بنسبة 100% داخل المتصفح.",
    "Need commercial 3D product visualizations, hero marketing stills, animations, or interactive WebAR models of this exact caliber? Connect with me directly to initiate your project.": "هل تحتاج إلى إظهار منتجات تجاري ثلاثي الأبعاد، أو لقطات تسويقية رئيسية، أو رسوم متحركة، أو نماذج WebAR تفاعلية بهذا المستوى المتقدم؟ تواصل معي مباشرة لبدء مشروعك.",
    "Normal Map Generator & Texture Suite | Free 3D In-Browser Tool": "مُوَلّد خرائط النورمال وحزمة الخامات | أداة 3D مجانية داخل المتصفح",
    "Normal maps generated from 2D pixel luminance are mathematical gradient approximations. For hero cinematic assets, high-to-low poly cage baking or Substance Painter is recommended.": "خرائط النورمال المولدة من سطوع البكسل ثنائي الأبعاد هي تقريبات تدرجية رياضية. للأصول السينمائية الرئيسية، يوصى بالخبز من المجسمات العالية (Baking) أو استخدام Substance Painter.",
    "On iOS devices, launches Apple QuickLook USDZ viewer. On Android, launches Google Scene Viewer. On desktop, generates a QR code to scan with your phone camera.": "على أجهزة iOS يفتح عارض Apple QuickLook بصيغة USDZ. على أجهزة Android يفتح Google Scene Viewer. على أجهزة الكمبيوتر يظهر رمز QR للمسح بكاميرا الهاتف.",
    "Optimized rotational symmetry for sharp geometric edges, masonry, and mechanical hard-surface relief.": "تناظر دوراني محسن للحواف الهندسية الحادة، والتفاصيل الحجرية، وبروز الأسطح الميكانيكية الصلبة.",
    "PBR Metallic-Roughness shader with applied normal texture in real-time.": "تظليل PBR المعدني-الخشن مع تطبيق خامة النورمال في الوقت الفعلي مباشرة.",
    "Package 3D models and optimize textures with WebP/JPEG compression. 100% private in-browser WebGL pipeline.": "تجميع نماذج الـ 3D وضغط الخامات بتقنية WebP وJPEG. سير عمل WebGL خصوصي 100% داخل المتصفح.",
    "Package multiple loose texture images (.png/.jpg) and .bin buffers into a single self-contained .glb binary file. Or extract any .glb into a downloadable ZIP archive.": "تجميع صور الخامات المنفصلة وملفات .bin في ملف ثنائي واحد .glb متكامل، أو فك ضغط أي ملف .glb إلى أرشيف ZIP قابل للتنزيل.",
    "Portfolio | Mustafa Jamal 3D Product & Furniture Visualization": "معرض الأعمال | مصطفى جمال - إظهار المنتجات والأثاث ثلاثي الأبعاد",
    "Pre-fills this project reference • 24h custom quote turnaround": "يتم ملء مرجع هذا المشروع تلقائياً • عرض سعر مخصص خلال 24 ساعة",
    "Ready to discuss your project specifications? Response within 24 hours.": "هل أنت مستعد لمناقشة مواصفات مشروعك؟ الرد خلال 24 ساعة.",
    "Reduce GLB file sizes by up to 80% for lightning-fast web loading.": "تقليل حجم ملفات الـ GLB بنسبة تصل إلى 80% لتحميل فائق السرعة على مواقع الويب.",
    "Rotating studio light highlights real-time surface relief and depth:": "إضاءة استوديو متحركة تبرز بروز السطح والعمق الفيزيائي في الوقت الفعلي:",
    "Search by model, material (PBR, Glass, Oak), software, or client...": "ابحث باسم الموديل، الخامة (PBR، زجاج، خشب)، البرنامج، أو العميل...",
    "Use the \"Invert Green\" toggle to match your target game engine or DCC tool.": "استخدم زر \"عكس القناة الخضراء\" لمطابقة محرك الألعاب أو برنامج التصميم المستهدف.",
