    "1. Product Modeling & Visualization": "1. Produktmodellierung & Visualisierung",
    "High-detail commercial 3D modeling and photorealistic studio rendering for cosmetics, electronics, beverages, and luxury products.": "Hochdetaillierte kommerzielle 3D-Modellierung und fotorealistisches Studio-Rendering für Kosmetik, Elektronik, Getränke und Luxusprodukte.",
    "2. E-commerce & Amazon Listing Images": "2. E-Commerce- & Amazon-Produktbilder",
    "Clean, compliant, high-converting product imagery created specifically for Amazon, Shopify, and global online retail listings.": "Saubere, richtlinienkonforme und verkaufsstarke Produktbilder speziell für Amazon, Shopify und globale Online-Shops.",
    "3. Furniture Modeling & Visualization": "3. Möbelmodellierung & Visualisierung",
    "Precise 3D furniture modeling, fabric draping, and photorealistic architectural staging for modern design ateliers and catalog publishers.": "Präzise 3D-Möbelmodellierung, Stofffalten-Simulation und fotorealistisches Staging für moderne Designstudios und Kataloge.",
    "4. Product Marketing Visuals & Animation": "4. Produktmarketing-Visuals & Animation",
    "Cinematic 3D animation, macro optical close-ups, and dynamic video spots created for high-impact brand campaigns and social media.": "Kinoreife 3D-Animationen, Makro-Nahaufnahmen und dynamische Videospots für reichweitenstarke Markenkampagnen und Social Media.",
    "5. AR-Ready 3D Assets & WebAR": "5. AR-Ready 3D-Assets & WebAR",
    "Lightweight, interactive 3D assets formatted for augmented reality and real-time WebGL configurators across mobile and desktop.": "Leichtgewichtige, interaktive 3D-Assets für Augmented Reality und WebGL-Konfiguratoren auf mobilen und Desktop-Endgeräten.",
    "6. 3D Printing / Print-Ready Models": "6. 3D-Druck / Druckfertige Modelle",
    "Watertight, manifold 3D models tailored for additive manufacturing, resin and FDM prototyping, and custom physical display designs.": "Wasserdichte (manifold) 3D-Modelle für additive Fertigung, Harz- und FDM-Prototyping sowie maßgeschneiderte Präsentationsmodelle.",
    "7. Real-Time Assets & Optimization": "7. Echtzeit-Assets & Optimierung",
    "Geometry retopology, high-to-low poly baking, and asset preparation engineered for real-time workflows and game engine pipelines.": "Geometrie-Retopologie, High-to-Low-Poly-Baking und Asset-Vorbereitung für Echtzeit-Pipelines und Game-Engines.",
    "8. Game Assets & Environments": "8. Game-Assets & Umgebungen",
