    "We structure every 3D visualization milestone from the initial brief to final delivery. Ensuring photoreal material shaders, clean geometry, strict confidentiality, and frictionless approvals aligned with your commercial goals.": "Nous structurons chaque étape de visualisation 3D, du brief initial à la livraison finale, en garantissant des shaders photoréalistes, une géométrie propre, une stricte confidentialité et des validations fluides.",
    "Milestone Approvals": "Validations par étapes",
    "Structured stage sign-offs—from clay blockouts to lighting and final master renders—guaranteeing zero wasted turnaround.": "Validations d'étapes structurées — du rendu argile (clay) à l'éclairage et aux rendus finaux — garantissant zéro temps perdu.",
    "Strict Confidentiality": "Confidentialité Stricte",
    "Full NDA compliance protecting proprietary product concepts, unreleased industrial models, and brand marketing IP from day one.": "Conformité totale aux accords de confidentialité (NDA) protégeant vos concepts exclusifs et votre propriété intellectuelle dès le premier jour.",
    "Clean Topology & Geometry": "Topologie & Géométrie Propres",
    "Quad-dominant, deformation-ready meshes built with precision edge flow, engineered for cinematic rendering and commercial assets.": "Maillages à dominante quad avec un flux d'arêtes précis, conçus pour le rendu cinématographique et les assets commerciaux.",
    "Photorealistic Materiality": "Matérialité Photoréaliste",
    "Rigorous study of light interaction, micro-surface dispersion, and calibrated PBR textures tailored for glass, metals, fabrics, and woods.": "Étude rigoureuse des interactions lumineuses, de la dispersion et des textures PBR calibrées pour le verre, les métaux, tissus et bois.",
    "Production Software Stack": "Suite Logicielle de Production",
    "Production-proven methodologies, industry software stack, and proprietary inspection pipeline.": "Méthodologies éprouvées en production, logiciels de référence de l'industrie et pipeline de contrôle propriétaire.",
    "Also Built — GLB Studio Pro": "Également développé — GLB Studio Pro",
    "A browser-based WebGL 2.0 viewer and PBR inspection studio designed to preview topology, inspect material channels, and QA 3D assets with mobile WebXR AR support before publishing online.": "Une visionneuse WebGL 2.0 et studio d'inspection PBR dans le navigateur pour prévisualiser la topologie, vérifier les textures et tester la RA WebXR.",
    "Open GLB Viewer": "Ouvrir la Visionneuse GLB",
