    "Start Project Request": "Démarrer une Demande",
    "1. Product Modeling & Visualization": "1. Modélisation & Visualisation de Produits",
    "High-detail commercial 3D modeling and photorealistic studio rendering for cosmetics, electronics, beverages, and luxury products.": "Modélisation 3D commerciale haute précision et rendu studio photoréaliste pour cosmétiques, électronique, boissons et produits de luxe.",
    "2. E-commerce & Amazon Listing Images": "2. Images pour E-commerce & Amazon",
    "Clean, compliant, high-converting product imagery created specifically for Amazon, Shopify, and global online retail listings.": "Images produits nettes, conformes et conçues pour maximiser les conversions sur Amazon, Shopify et le retail en ligne.",
    "3. Furniture Modeling & Visualization": "3. Modélisation & Visualisation de Mobilier",
    "Precise 3D furniture modeling, fabric draping, and photorealistic architectural staging for modern design ateliers and catalog publishers.": "Modélisation précise de mobilier, simulation de tissus et mise en scène architecturale photoréaliste pour catalogues et créateurs.",
    "4. Product Marketing Visuals & Animation": "4. Visuels Marketing & Animation 3D",
    "Cinematic 3D animation, macro optical close-ups, and dynamic video spots created for high-impact brand campaigns and social media.": "Animation 3D cinématographique, gros plans macro et spots vidéo dynamiques créés pour campagnes de marque et réseaux sociaux.",
    "5. AR-Ready 3D Assets & WebAR": "5. Assets 3D Prêts pour la RA & WebAR",
    "Lightweight, interactive 3D assets formatted for augmented reality and real-time WebGL configurators across mobile and desktop.": "Assets 3D légers et interactifs optimisés pour la réalité augmentée et les configurateurs WebGL sur mobile et ordinateur.",
    "6. 3D Printing / Print-Ready Models": "6. Modèles Prêts pour l'Impression 3D",
    "Watertight, manifold 3D models tailored for additive manufacturing, resin and FDM prototyping, and custom physical display designs.": "Modèles 3D étanches et sans défauts de maillage (manifold) conçus pour la fabrication additive, le prototypage résine et FDM.",
    "7. Real-Time Assets & Optimization": "7. Assets Temps Réel & Optimisation",
    "Geometry retopology, high-to-low poly baking, and asset preparation engineered for real-time workflows and game engine pipelines.": "Retopologie de géométrie, baking high-to-low poly et préparation d'assets pour moteurs de jeux et flux temps réel.",
    "8. Game Assets & Environments": "8. Assets de Jeu & Environnements",
