    "Reference photos, dimensions/blueprints, sketches, or standard 3D file formats (Blender .blend, OBJ, FBX, GLTF).": "Photos de référence, cotes/plans, croquis ou formats 3D standards (Blender .blend, OBJ, FBX, GLTF).",
