    "Millimeter-accurate 3D modeling, cinematic raytracing, product animations, and interactive WebAR assets for luxury brands and manufacturers.": "Modélisation 3D au millimètre près, raytracing cinématographique, animations de produits et assets WebAR interactifs pour marques de luxe.",
    "Mustafa Jamal. All Rights Reserved. Built with 100% Client-Side WebGL Architecture.": "Mustafa Jamal. Tous droits réservés. Conçu avec une architecture WebGL 100% côté client.",
    "Need commercial 3D product visualizations, hero marketing stills, animations, or interactive WebAR models of this exact caliber? Connect with me directly to initiate your project.": "Besoin de visualisations 3D de produits, d'images marketing phares, d'animations ou de modèles WebAR de ce calibre ? Contactez-moi directement.",
    "Normal Map Generator & Texture Suite | Free 3D In-Browser Tool": "Générateur de Normal Maps & Suite de Textures | Outil 3D Gratuit dans le Navigateur",
    "Normal maps generated from 2D pixel luminance are mathematical gradient approximations. For hero cinematic assets, high-to-low poly cage baking or Substance Painter is recommended.": "Les normal maps générées à partir de la luminance 2D sont des approximations mathématiques. Pour les assets cinématographiques, le baking high-to-low poly ou Substance Painter est recommandé.",
    "On iOS devices, launches Apple QuickLook USDZ viewer. On Android, launches Google Scene Viewer. On desktop, generates a QR code to scan with your phone camera.": "Sur iOS, lance la visionneuse Apple QuickLook USDZ. Sur Android, ouvre Google Scene Viewer. Sur ordinateur, génère un QR code à scanner avec votre smartphone.",
    "Optimized rotational symmetry for sharp geometric edges, masonry, and mechanical hard-surface relief.": "Symétrie rotationnelle optimisée pour arêtes géométriques vives, maçonnerie et reliefs mécaniques.",
    "PBR Metallic-Roughness shader with applied normal texture in real-time.": "Shader PBR Métallique-Rugosité avec texture normale appliquée en temps réel.",
    "Package 3D models and optimize textures with WebP/JPEG compression. 100% private in-browser WebGL pipeline.": "Empaquetez des modèles 3D et compressez les textures en WebP/JPEG. Pipeline WebGL 100% privé dans le navigateur.",
    "Package multiple loose texture images (.png/.jpg) and .bin buffers into a single self-contained .glb binary file. Or extract any .glb into a downloadable ZIP archive.": "Regroupez plusieurs textures et tampons .bin dans un fichier binaire .glb unique, ou extrayez tout .glb dans un ZIP téléchargeable.",
    "Portfolio | Mustafa Jamal 3D Product & Furniture Visualization": "Portfolio | Mustafa Jamal Visualisation 3D de Produits & Mobilier",
    "Pre-fills this project reference • 24h custom quote turnaround": "Pré-remplit la référence de ce projet • Devis personnalisé sous 24h",
