    "3. Furniture Modeling & Visualization": "3. Modellazione & Visualizzazione Arredo",
    "Precise 3D furniture modeling, fabric draping, and photorealistic architectural staging for modern design ateliers and catalog publishers.": "Modellazione accurata di arredi, simulazione di tessuti e ambientazioni architettoniche fotorrealistiche per cataloghi e studi di design.",
