    "Millimeter-accurate 3D modeling, cinematic raytracing, product animations, and interactive WebAR assets for luxury brands and manufacturers.": "Modellazione 3D con precisione millimetrica, raytracing cinematografico, animazioni di prodotto e asset WebAR per marchi di lusso.",
    "Mustafa Jamal. All Rights Reserved. Built with 100% Client-Side WebGL Architecture.": "Mustafa Jamal. Tutti i diritti riservati. Sviluppato con architettura WebGL al 100% lato client.",
    "Need commercial 3D product visualizations, hero marketing stills, animations, or interactive WebAR models of this exact caliber? Connect with me directly to initiate your project.": "Hai bisogno di visualizzazioni 3D di prodotto, immagini chiave di marketing, animazioni o modelli WebAR di questo livello? Contattami direttamente per avviare il tuo progetto.",
    "Normal Map Generator & Texture Suite | Free 3D In-Browser Tool": "Generatore di Normal Map & Suite Texture | Strumento 3D Gratuito nel Browser",
    "Normal maps generated from 2D pixel luminance are mathematical gradient approximations. For hero cinematic assets, high-to-low poly cage baking or Substance Painter is recommended.": "Le normal map generate dalla luminanza 2D sono approssimazioni matematiche. Per asset cinematografici di punta si consiglia il baking high-to-low poly o Substance Painter.",
    "On iOS devices, launches Apple QuickLook USDZ viewer. On Android, launches Google Scene Viewer. On desktop, generates a QR code to scan with your phone camera.": "Su iOS avvia il visualizzatore Apple QuickLook USDZ. Su Android avvia Google Scene Viewer. Su desktop genera un codice QR da scansionare con la fotocamera del telefono.",
    "Optimized rotational symmetry for sharp geometric edges, masonry, and mechanical hard-surface relief.": "Simmetria rotazionale ottimizzata per spigoli geometrici netti, muratura e rilievi meccanici hard-surface.",
    "PBR Metallic-Roughness shader with applied normal texture in real-time.": "Shader PBR Metallo-Rugosità con texture normale applicata in tempo reale.",
    "Package 3D models and optimize textures with WebP/JPEG compression. 100% private in-browser WebGL pipeline.": "Impacchetta modelli 3D e ottimizza le texture con compressione WebP/JPEG. Pipeline WebGL al 100% privata nel browser.",
    "Package multiple loose texture images (.png/.jpg) and .bin buffers into a single self-contained .glb binary file. Or extract any .glb into a downloadable ZIP archive.": "Unisci immagini texture sciolte e buffer .bin in un singolo file binario .glb, oppure estrai qualsiasi .glb in un archivio ZIP scaricabile.",
    "Portfolio | Mustafa Jamal 3D Product & Furniture Visualization": "Portfolio | Mustafa Jamal Visualizzazione 3D di Prodotti e Arredo",
    "Pre-fills this project reference • 24h custom quote turnaround": "Pre-compila il riferimento di questo progetto • Preventivo personalizzato entro 24 ore",
    "Ready to discuss your project specifications? Response within 24 hours.": "Pronto a discutere le specifiche del tuo progetto? Risposta entro 24 ore.",
