    "Commercial 3D product visualization showcasing realistic optical dispersion (caustics) through heavy tinted crystal glass, internal liquid meniscus absorption, laser-etched silver typographic displacement, and atmospheric desert night lighting calibrated for global luxury campaigns.": "Visualizzazione 3D commerciale di prodotto che mette in risalto la dispersione ottica realistica attraverso cristallo colorato pesante, assorbimento del menisco liquido, tipografia incisa a laser e illuminazione notturna nel deserto per campagne di lusso internazionali.",
    "Extreme precision hard-surface 3D modeling reproducing the iconic Rolex Daytona chronograph. Features micro-chamfers, true-to-life optical refraction through the domed sapphire crystal, realistic luminescent paint illumination, and anisotropic hand-finished brushed metal textures.": "Modellazione 3D hard-surface di altissima precisione dell'iconico cronografo Rolex Daytona. Include micro-smussature, rifrazione ottica fedele attraverso il vetro zaffiro bombato, vernice luminescente e texture metalliche spazzolate anisotropiche.",
    "Precision hard-surface 3D modeling and recreation of professional photographic equipment. Features realistic tactile rubber knurling on grip and dials, multi-coated anti-reflective glass elements, and laser-engraved camera branding.": "Modellazione 3D hard-surface di precisione di attrezzatura fotografica professionale. Presenta zigrinatura in gomma su impugnatura e ghiere, elementi in vetro antiriflesso multistrato e incisioni laser del brand.",
    "Intricate mechanical modeling exploring complex interweaving metal curves, cast-metal surface imperfections, polycarbonate dispersion, and flawless quad-based subdivision surface topology.": "Complessa modellazione meccanica con curve metalliche intrecciate, imperfezioni superficiali di metallo fuso, dispersione del policarbonato e perfetta topologia di suddivisione a soli quadrilateri.",
    "A dedicated showcase of production-grade additive manufacturing 3D assets. Features complete interlocking modular assemblies, wall-thickness analysis, thread clearances, snap-fit tolerances, and export-ready watertight STL part files for physical fabrication and rapid prototyping.": "Vetrina di modelli 3D industriali per produzione additiva. Presenta assemblaggi modulari ad incastro, analisi degli spessori di parete, tolleranze di accoppiamento a scatto e file STL a tenuta stagna pronti per la fabbricazione rapida.",
    "Commercial product visualization highlighting industrial mounting hardware. Demonstrates precision mechanical joints, locking collar mechanisms, cable routing channels, and durable powder-coated steel surface shaders.": "Visualizzazione di prodotto commerciale su sistemi di montaggio industriale. Mostra giunti meccanici di precisione, meccanismi con collare di bloccaggio, canaline passacavi e resistenti finiture in acciaio verniciato a polvere.",
    "Precision hard-surface 3D modeling and turntable animation showcase of a sleek modern cylinder smart speaker. Demonstrates procedural micro-hole perforated acoustic grilles, capacitive top control rings, and smooth cinematic 360-degree orbital camera motion.": "Modellazione hard-surface di precisione e animazione orbitale di uno smart speaker cilindrico moderno. Dimostra griglie acustiche con microfori procedurali, anelli di controllo capacitivi superiori e fluidi movimenti di camera a 360 gradi.",
    "Full commercial CGI product animation featuring procedural condensation water droplets, can tab mechanics, embossed aluminum displacement, and explosive cinematic smoke and rim lighting calibrated for commercial advertising.": "Animazione pubblicitaria CGI completa con gocce di condensa procedurali, meccanica della linguetta della lattina, sbalzo dell'alluminio e fumo scenografico con illuminazione d'accento per campagne pubblicitarie.",
    "Complete real-time asset pipeline demonstrating sub-5MB GLB models, baked PBR textures (Albedo, Roughness, Metalness, Normal, AO), and seamless WebXR compatibility for iOS QuickLook and Android Scene Viewer.": "Pipeline completa di asset in tempo reale che include modelli GLB inferiori a 5MB, texture PBR consolidate e perfetta compatibilità WebXR per iOS QuickLook e Android Scene Viewer.",
    "Flagship seating collection featuring compound curve subdivision modeling, realistic micro-fiber bouclé fabric shaders, procedural wood grain joinery, and clean quad topology passes across Capotoni, Caledonian, Finn, and Oculus lounge chairs.": "Collezione ammiraglia di sedute con modellazione a curve composte, shader per tessuto bouclé in microfibra fotorealistico, venature del legno procedurali e topologia quad impeccabile per le poltrone Capotoni, Caledonian, Finn e Oculus.",
    "Production game asset workflow: high-poly to low-poly baking, hand-crafted normal decals, edge wear masks, and modular texture reuse calibrated for modern real-time game engines.": "Flusso di lavoro per asset di videogiochi di livello produttivo: baking da high-poly a low-poly, decalcomanie normali artigianali, maschere di usura dei bordi e riutilizzo modulare delle texture per i moderni motori grafici.",
    "Photorealistic period prop visualization. Features multi-layered roughness variation, peeling enamel paint, rust and dirt accumulation in crevices, and physical light transmission through an imperfect cylindrical glass mantle.": "Visualizzazione fotorealistica di scena d'epoca. Presenta variazioni di ruvidezza multistrato, vernice a smalto scrostata, ruggine e polvere nelle fessure, e trasmissione fisica della luce attraverso un cilindro di vetro imperfetto.",
    "Hyper-detailed weapons modeling capturing genuine Japanese swordsmithing methods. Features differential hardening blade line (Hamon), intricate cord tsuka-ito wrap over stingray skin, and aged patina metalwork.": "Modellazione di armi iper-dettagliata che riproduce i metodi di forgiatura giapponese. Presenta la linea di tempra differenziata Hamon, complessa legatura tsuka-ito su pelle di razza e finiture metalliche con patina anticata.",
    "Sophisticated bedroom furniture visualization displaying cloth simulation draping, wrinkled linen sheets, velvet upholstered vertical channels, and warm layered ambient lighting across the Royal and Metal bed collections.": "Sofisticata visualizzazione di mobili per la camera da letto che mostra drappeggi con simulazione di tessuti, lenzuola in lino spiegazzate, canali verticali imbottiti in velluto e calda illuminazione d'ambiente stratificata.",
    "Carefully crafted hardwood living furniture emphasizing traditional joinery craftsmanship, continuous wood grain orientation along organic edges, and natural diffused sunlight illumination across the Vintage Coffee Table and TV Stand.": "Mobili da soggiorno in legno massello finemente realizzati che valorizzano la lavorazione tradizionale a incastro, la venatura continua del legno lungo i bordi organici e l'illuminazione solare naturale diffusa.",
    "High-performance real-time environment asset pack engineered for DCS World and military simulation engines. Features strictly controlled draw-calls, shared texture atlases, multiple LOD stages, and optimized collision meshes.": "Pacchetto di asset ambientali in tempo reale ad alte prestazioni per DCS World e simulatori militari. Include draw-call rigorosamente controllate, texture atlas condivisi, livelli di dettaglio (LOD) multipli e mesh di collisione ottimizzate.",
    "Massive real-time architectural environment combining modular stone masonry, timber framing, shoreline wave foam displacement, and volumetric atmospheric lighting for next-gen game engines.": "Imponente ambiente architettonico in tempo reale che unisce muratura modulare in pietra, travature in legno, crespature e schiuma delle onde costiere e illuminazione volumetrica atmosferica per motori di gioco next-gen.",
