    "How Precision is Crafted,": "Cómo se crea la precisión,",
    "Step by Step": "Paso a paso",
    "We structure every 3D visualization milestone from the initial brief to final delivery. Ensuring photoreal material shaders, clean geometry, strict confidentiality, and frictionless approvals aligned with your commercial goals.": "Estructuramos cada etapa de visualización 3D desde el informe inicial hasta la entrega final, garantizando shaders fotorrealistas, geometría limpia, confidencialidad estricta y aprobaciones fluidas.",
    "Milestone Approvals": "Aprobaciones por fases",
    "Structured stage sign-offs—from clay blockouts to lighting and final master renders—guaranteeing zero wasted turnaround.": "Aprobaciones estructurate por fases — desde modelos de arcilla hasta iluminación y renders finales — garantizando cero pérdida de tiempo.",
    "Strict Confidentiality": "Estricta Confidencialidad",
    "Full NDA compliance protecting proprietary product concepts, unreleased industrial models, and brand marketing IP from day one.": "Cumplimiento total de acuerdos de confidencialidad (NDA) para proteger tus conceptos y modelos no lanzados desde el primer día.",
    "Clean Topology & Geometry": "Topología y Geometría Limpia",
    "Quad-dominant, deformation-ready meshes built with precision edge flow, engineered for cinematic rendering and commercial assets.": "Mallas predominantemente de cuadriláteros con flujo de bordes preciso, diseñadas para renderizado cinematográfico y activos comerciales.",
    "Photorealistic Materiality": "Materialidad Fotorrealista",
    "Rigorous study of light interaction, micro-surface dispersion, and calibrated PBR textures tailored for glass, metals, fabrics, and woods.": "Estudio riguroso de la interacción de la luz, dispersión superficial y texturas PBR calibradas para vidrio, metales, telas y maderas.",
    "Production Software Stack": "Suite de Software de Producción",
    "Production-proven methodologies, industry software stack, and proprietary inspection pipeline.": "Metodologías probadas en producción, software líder de la industria y flujo de verificación propietario.",
    "Also Built — GLB Studio Pro": "También desarrollado — GLB Studio Pro",
    "A browser-based WebGL 2.0 viewer and PBR inspection studio designed to preview topology, inspect material channels, and QA 3D assets with mobile WebXR AR support before publishing online.": "Un visor WebGL 2.0 e inspección PBR en el navegador para revisar topología, canales de material y soporte WebXR AR antes de publicar.",
