    "High-detail commercial 3D modeling and photorealistic studio rendering for cosmetics, electronics, beverages, and luxury products.": "Modelado 3D comercial de alto detalle y renderizado de estudio fotorrealista para cosméticos, electrónica, bebidas y productos de lujo.",
    "2. E-commerce & Amazon Listing Images": "2. Imágenes para Comercio Electrónico y Amazon",
    "Clean, compliant, high-converting product imagery created specifically for Amazon, Shopify, and global online retail listings.": "Imágenes de producto limpias, conformes y optimizadas para conversión diseñadas para Amazon, Shopify y tiendas online globales.",
    "3. Furniture Modeling & Visualization": "3. Modelado y Visualización de Mobiliario",
    "Precise 3D furniture modeling, fabric draping, and photorealistic architectural staging for modern design ateliers and catalog publishers.": "Modelado preciso de mobiliario, drapeado de telas y escenografía arquitectónica fotorrealista para catálogos y estudios de diseño.",
    "4. Product Marketing Visuals & Animation": "4. Visuales de Marketing y Animación 3D",
    "Cinematic 3D animation, macro optical close-ups, and dynamic video spots created for high-impact brand campaigns and social media.": "Animación 3D cinematográfica, primeros planos macro y spots de video dinámicos para campañas de marca y redes sociales de gran impacto.",
    "5. AR-Ready 3D Assets & WebAR": "5. Activos 3D Listos para RA y WebAR",
    "Lightweight, interactive 3D assets formatted for augmented reality and real-time WebGL configurators across mobile and desktop.": "Activos 3D ligeros e interactivos preparados para realidad aumentada y configuradores WebGL en móviles y ordenadores.",
    "6. 3D Printing / Print-Ready Models": "6. Modelos Listos para Impresión 3D",
    "Watertight, manifold 3D models tailored for additive manufacturing, resin and FDM prototyping, and custom physical display designs.": "Modelos 3D herméticos (manifold) preparados para fabricación aditiva, prototipado en resina y FDM, y exhibiciones físicas.",
    "7. Real-Time Assets & Optimization": "7. Activos en Tiempo Real y Optimización",
    "Geometry retopology, high-to-low poly baking, and asset preparation engineered for real-time workflows and game engine pipelines.": "Retopología de geometría, horneado (baking) de alta a baja poligonización y preparación de activos para motores de juegos.",
    "8. Game Assets & Environments": "8. Activos para Videojuegos y Entornos",
