    "Millimeter-accurate 3D modeling, cinematic raytracing, product animations, and interactive WebAR assets for luxury brands and manufacturers.": "Modelado 3D con precisión milimétrica, trazado de rayos cinematográfico, animaciones de productos y activos WebAR para marcas de lujo.",
    "Mustafa Jamal. All Rights Reserved. Built with 100% Client-Side WebGL Architecture.": "Mustafa Jamal. Todos los derechos reservados. Desarrollado con arquitectura WebGL 100% del lado del cliente.",
    "Need commercial 3D product visualizations, hero marketing stills, animations, or interactive WebAR models of this exact caliber? Connect with me directly to initiate your project.": "¿Necesitas visualizaciones 3D de productos, imágenes de marketing principales, animaciones o modelos WebAR de este calibre? Contáctame directamente para iniciar tu proyecto.",
    "Normal Map Generator & Texture Suite | Free 3D In-Browser Tool": "Generador de Normal Maps y Suite de Texturas | Herramienta 3D Gratuita en el Navegador",
    "Normal maps generated from 2D pixel luminance are mathematical gradient approximations. For hero cinematic assets, high-to-low poly cage baking or Substance Painter is recommended.": "Los mapas de normales generados a partir de luminancia 2D son aproximaciones matemáticas. Para activos cinematográficos principales se recomienda baking de alta a baja o Substance Painter.",
    "On iOS devices, launches Apple QuickLook USDZ viewer. On Android, launches Google Scene Viewer. On desktop, generates a QR code to scan with your phone camera.": "En dispositivos iOS abre el visor Apple QuickLook USDZ. En Android abre Google Scene Viewer. En escritorio genera un código QR para escanear con la cámara del móvil.",
    "Optimized rotational symmetry for sharp geometric edges, masonry, and mechanical hard-surface relief.": "Simetría rotacional optimizada para bordes geométricos nítidos, mampostería y relieves mecánicos.",
    "PBR Metallic-Roughness shader with applied normal texture in real-time.": "Sombreador PBR Metálico-Rugoso con textura de normales aplicada en tiempo real.",
    "Package 3D models and optimize textures with WebP/JPEG compression. 100% private in-browser WebGL pipeline.": "Empaqueta modelos 3D y optimiza texturas con compresión WebP/JPEG. Flujo WebGL 100% privado en el navegador.",
    "Package multiple loose texture images (.png/.jpg) and .bin buffers into a single self-contained .glb binary file. Or extract any .glb into a downloadable ZIP archive.": "Empaqueta imágenes de texturas sueltas y buffers .bin en un único archivo binario .glb, o extrae cualquier .glb en un archivo ZIP descargable.",
    "Portfolio | Mustafa Jamal 3D Product & Furniture Visualization": "Portafolio | Mustafa Jamal Visualización 3D de Productos y Mobiliario",
    "Pre-fills this project reference • 24h custom quote turnaround": "Rellena automáticamente la referencia de este proyecto • Cotización personalizada en 24h",
