    "Skip the high cost of shipping heavy furniture or renting physical studios. Every lifestyle scene is staged 100% digitally with zero risk of sample damage or transit delays.": "Ağır mobilyaları taşımak veya pahalı stüdyolar kiralamak zorunda kalmayın. Her yaşam alanı kurgusu numune hasarı riski olmadan %100 dijital olarak üretilir.",
