    "I’m": "Ben",
    "About & Studio Pipeline | Mustafa Jamal 3D Artist": "Hakkımda & Stüdyo İş Akışı | Mustafa Jamal 3D Sanatçısı",
    "3D PRODUCT VISUALIZER": "3D ÜRÜN GÖRSELLEŞTİRİCİ",
    "3D Product Visualization & Modeling for E-Commerce and Digital Experiences": "E-Ticaret ve Dijital Deneyimler İçin 3D Ürün Görselleştirme ve Modelleme",
    "How Precision is Crafted,": "Hassasiyet Nasıl Üretilir,",
    "Step by Step": "Adım Adım",
    "We structure every 3D visualization milestone from the initial brief to final delivery. Ensuring photoreal material shaders, clean geometry, strict confidentiality, and frictionless approvals aligned with your commercial goals.": "İlk brief aşamasından nihai teslimata kadar her 3D görselleştirme adımını titizlikle yapılandırıyoruz. Fotogerçekçi malzemeler, temiz geometri, tam gizlilik ve sorunsuz onay süreçleri sağlıyoruz.",
    "Milestone Approvals": "Aşama Onayları",
    "Structured stage sign-offs—from clay blockouts to lighting and final master renders—guaranteeing zero wasted turnaround.": "Kil blok modellerden ışıklandırma ve nihai renderlara kadar yapılandırılmış aşama onayları ile zaman kaybını sıfıra indiriyoruz.",
    "Strict Confidentiality": "Tam Gizlilik Garantisi",
    "Full NDA compliance protecting proprietary product concepts, unreleased industrial models, and brand marketing IP from day one.": "Tescilli ürün konseptlerinizi, henüz duyurulmamış modellerinizi ve marka haklarınızı ilk günden koruyan tam NDA uyumluluğu.",
    "Clean Topology & Geometry": "Temiz Topoloji & Geometri",
    "Quad-dominant, deformation-ready meshes built with precision edge flow, engineered for cinematic rendering and commercial assets.": "Hassas kenar akışına sahip quad ağırlıklı mesh yapıları; sinematik renderlar ve ticari varlıklar için optimize edilmiştir.",
    "Photorealistic Materiality": "Fotogerçekçi Malzeme Doku",
    "Rigorous study of light interaction, micro-surface dispersion, and calibrated PBR textures tailored for glass, metals, fabrics, and woods.": "Cam, metal, kumaş ve ahşap için ışık etkileşimleri, mikro yüzey dağılımı ve kalibre edilmiş PBR dokuların titizlikle incelenmesi.",
    "Production Software Stack": "Kullanılan Profesyonel Yazılımlar",
    "Production-proven methodologies, industry software stack, and proprietary inspection pipeline.": "Üretimde kanıtlanmış yöntemler, endüstri standardı yazılımlar ve tescilli denetim iş akışları.",
    "Also Built — GLB Studio Pro": "Ayrıca Geliştirdiğim — GLB Studio Pro",
    "A browser-based WebGL 2.0 viewer and PBR inspection studio designed to preview topology, inspect material channels, and QA 3D assets with mobile WebXR AR support before publishing online.": "Tarayıcı tabanlı WebGL 2.0 görüntüleyici ve PBR denetim stüdyosu; modelleri yayınlamadan önce topoloji, malzeme ve WebXR AR desteğini test eder.",
    "Open GLB Viewer": "GLB Görüntüleyiciyi Aç",
    "Explore Showcase": "Projeleri İncele",
    "Start Project Request": "Proje Talebi Başlat",
    "1. Product Modeling & Visualization": "1. Ürün Modelleme & Görselleştirme",
    "High-detail commercial 3D modeling and photorealistic studio rendering for cosmetics, electronics, beverages, and luxury products.": "Kozmetik, elektronik, içecek ve lüks tüketim ürünleri için yüksek detaylı 3D modelleme ve fotogerçekçi stüdyo renderları.",
    "2. E-commerce & Amazon Listing Images": "2. E-Ticaret & Amazon Ürün Görselleri",
    "Clean, compliant, high-converting product imagery created specifically for Amazon, Shopify, and global online retail listings.": "Amazon, Shopify ve küresel e-ticaret siteleri için yüksek dönüşüm sağlayan, platform kurallarına %100 uygun ürün görselleri.",
    "3. Furniture Modeling & Visualization": "3. Mobilya Modelleme & Görselleştirme",
    "Precise 3D furniture modeling, fabric draping, and photorealistic architectural staging for modern design ateliers and catalog publishers.": "Modern mobilya üreticileri ve katalog yayıncıları için milimetrik mobilya modelleme, kumaş simülasyonu ve mimari ortam yerleşimi.",
    "4. Product Marketing Visuals & Animation": "4. Ürün Pazarlama Görselleri & 3D Animasyon",
    "Cinematic 3D animation, macro optical close-ups, and dynamic video spots created for high-impact brand campaigns and social media.": "Yüksek etkili marka lansmanları ve sosyal medya kampanyaları için sinematik 3D animasyonlar, makro yakın çekimler ve dinamik reklam videoları.",
    "5. AR-Ready 3D Assets & WebAR": "5. AR-Uyumlu 3D Varlıklar & WebAR",
    "Lightweight, interactive 3D assets formatted for augmented reality and real-time WebGL configurators across mobile and desktop.": "Mobil ve masaüstü tarayıcılarda çalışan artırılmış gerçeklik (AR) ve gerçek zamanlı WebGL ürün konfigüratörleri için optimize modeller.",
    "6. 3D Printing / Print-Ready Models": "6. 3D Baskıya Hazır Modeller",
    "Watertight, manifold 3D models tailored for additive manufacturing, resin and FDM prototyping, and custom physical display designs.": "Katmanlı üretim, reçine ve FDM prototipleme ve özel fiziksel stant tasarımları için hatasız, kapalı (manifold) 3D modeller.",
    "7. Real-Time Assets & Optimization": "7. Gerçek Zamanlı Varlıklar & Optimizasyon",
    "Geometry retopology, high-to-low poly baking, and asset preparation engineered for real-time workflows and game engine pipelines.": "Gerçek zamanlı iş akışları ve oyun motorları için geometri retopolojisi, yüksekten düşüğe poligon baking ve varlık hazırlığı.",
    "8. Game Assets & Environments": "8. Oyun Varlıkları & Çevre Tasarımı",
    "Hard-surface props, environmental modular pieces, and game-ready structures with clean PBR textures.": "Temiz PBR dokulara sahip hard-surface sahne donanımları, modüler çevre parçaları ve oyun motoruna hazır yapılar.",
    "Ready to Commission Production-Ready 3D Assets?": "Üretime Hazır 3D Varlıklar İçin Başlamaya Hazır mısınız?",
