    "Millimeter-accurate 3D modeling, cinematic raytracing, product animations, and interactive WebAR assets for luxury brands and manufacturers.": "Lüks markalar ve üreticiler için milimetrik hassasiyette 3D modelleme, sinematik ışın izleme, ürün animasyonları ve etkileşimli WebAR varlıkları.",
    "Mustafa Jamal. All Rights Reserved. Built with 100% Client-Side WebGL Architecture.": "Mustafa Jamal. Tüm Hakları Saklıdır. %100 Cihaz İçi WebGL Mimarisi ile Geliştirilmiştir.",
    "Need commercial 3D product visualizations, hero marketing stills, animations, or interactive WebAR models of this exact caliber? Connect with me directly to initiate your project.": "Tam olarak bu kalitede ticari 3D ürün görselleştirmeleri, ana pazarlama görselleri, animasyonlar veya etkileşimli WebAR modelleri mi arıyorsunuz? Projenizi başlatmak için doğrudan iletişime geçin.",
    "Normal Map Generator & Texture Suite | Free 3D In-Browser Tool": "Normal Haritası Üretici & Doku Paketi | Tarayıcı İçi Ücretsiz 3D Araç",
    "Normal maps generated from 2D pixel luminance are mathematical gradient approximations. For hero cinematic assets, high-to-low poly cage baking or Substance Painter is recommended.": "2D piksel parlaklığından üretilen normal haritaları matematiksel gradyan yaklaşımlarıdır. Sinematik ana varlıklar için yüksekten düşüğe poligon baking veya Substance Painter önerilir.",
    "On iOS devices, launches Apple QuickLook USDZ viewer. On Android, launches Google Scene Viewer. On desktop, generates a QR code to scan with your phone camera.": "iOS cihazlarda Apple QuickLook USDZ görüntüleyiciyi, Android'de Google Scene Viewer'ı başlatır. Masaüstünde ise telefon kameranızla taramanız için bir QR kod üretir.",
    "Optimized rotational symmetry for sharp geometric edges, masonry, and mechanical hard-surface relief.": "Keskin geometrik kenarlar, taş dokuları ve mekanik sert yüzey kabartmaları için optimize edilmiş dönme simetrisi.",
    "PBR Metallic-Roughness shader with applied normal texture in real-time.": "Gerçek zamanlı uygulanan normal dokusu ile PBR Metalik-Pürüzlülük gölgelendiricisi.",
    "Package 3D models and optimize textures with WebP/JPEG compression. 100% private in-browser WebGL pipeline.": "3D modelleri paketleyin ve dokuları WebP/JPEG sıkıştırmasıyla optimize edin. %100 yerel tarayıcı içi WebGL iş akışı.",
    "Package multiple loose texture images (.png/.jpg) and .bin buffers into a single self-contained .glb binary file. Or extract any .glb into a downloadable ZIP archive.": "Birden fazla ayrık doku görselini ve .bin tamponunu tek bir bağımsız .glb ikili dosyasında birleştirin veya herhangi bir .glb dosyasını indirilebilir ZIP arşivine dönüştürün.",
    "Portfolio | Mustafa Jamal 3D Product & Furniture Visualization": "Portföy | Mustafa Jamal 3D Ürün & Mobilya Görselleştirme",
    "Pre-fills this project reference • 24h custom quote turnaround": "Bu proje referansını otomatik doldurur • 24 saat içinde özel fiyat teklifi",
    "Ready to discuss your project specifications? Response within 24 hours.": "Proje detaylarınızı görüşmeye hazır mısınız? 24 saat içinde yanıt verilir.",
    "Reduce GLB file sizes by up to 80% for lightning-fast web loading.": "Web sitelerinde yıldırım hızında yükleme için GLB dosya boyutlarını %80'e kadar küçültün.",
    "Rotating studio light highlights real-time surface relief and depth:": "Dönen stüdyo ışığı, gerçek zamanlı yüzey kabartmasını ve derinliğini vurgular:",
