    "Marvelous Designer fabric physics, detailed seam micro-displacement, and procedural leather wear.": "基于 Marvelous Designer 的超逼真面料重力下垂模拟、高密接缝位移与程序化真皮肌理。",
    "Sub-D quad topology, physical dispersion shaders, and high-accuracy glass refraction.": "高标准 Sub-D 细分四边面布线、真实光谱物理色散着色器通道与精密光学折射模拟。",
    "Precision hard-surface modeling, studio calibrated light rig, pure white background (RGB 255).": "高精硬表面工业结构建模、专业影棚校准灯光系统与纯白底无杂色背景 (RGB 255)。",
    "Preserves Base Color, Roughness, Metallic, Normal Maps, Emissive, and Ambient Occlusion channels correctly without loss of color space.": "严谨完整保留基础漫反射、粗糙度、金属度、法线、自发光与环境光遮蔽等全部通道，杜绝色彩空间失真。",
    "Reference photos, dimensions/blueprints, sketches, or standard 3D file formats (Blender .blend, OBJ, FBX, GLTF).": "实物高清参考照片、尺寸规格工业图纸、草图手绘，或现有通用三维工程源文件 (Blender .blend, OBJ, FBX, GLTF)。",
    "Standard 3x3 convolution with smooth gradient transitions. Ideal for organic fabrics and leather.": "采用 3x3 空间平滑卷积核算法，渐变自然过度，专为织物软包与天然皮质纹理量身调校。",
    "Technical scope, geometry execution, and production deliverables behind selected commercial projects.": "深度复盘精选商业案例背后的硬核技术指标、三维网格执行方案与工业级交付物清单。",
