    "Extreme precision hard-surface 3D modeling reproducing the iconic Rolex Daytona chronograph. Features micro-chamfers, true-to-life optical refraction through the domed sapphire crystal, realistic luminescent paint illumination, and anisotropic hand-finished brushed metal textures.": "极限精度硬表面3D建模重现经典劳力士迪通拿机械计时腕表。具备微米级倒角导角、穹顶蓝宝石水晶镜面真实折射、逼真夜光涂料发光以及手工各向异性拉丝金属微观质感。",
    "Precision hard-surface 3D modeling and recreation of professional photographic equipment. Features realistic tactile rubber knurling on grip and dials, multi-coated anti-reflective glass elements, and laser-engraved camera branding.": "专业摄影器材超写实高精硬表面建模。真实呈现手柄与转盘上的防滑滚花橡胶触感、多层抗反射消色差光学玻璃镜片以及激光微米级雕刻相机机身标识。",
    "Intricate mechanical modeling exploring complex interweaving metal curves, cast-metal surface imperfections, polycarbonate dispersion, and flawless quad-based subdivision surface topology.": "精雕细琢的机械硬表面建模，深度探索精密交织的金属流线、铸造金属微观表面瑕疵、聚碳酸酯透光色散以及完美的纯四边形曲面细分布线拓扑。",
    "A dedicated showcase of production-grade additive manufacturing 3D assets. Features complete interlocking modular assemblies, wall-thickness analysis, thread clearances, snap-fit tolerances, and export-ready watertight STL part files for physical fabrication and rapid prototyping.": "工业级增材制造3D模型资产深度展示。具备完整的嵌套互锁模块化装配体、壁厚与干涉分析、螺纹配合公差、卡扣结构校准以及全封闭无缝流道STL直接交付文件。",
    "Commercial product visualization highlighting industrial mounting hardware. Demonstrates precision mechanical joints, locking collar mechanisms, cable routing channels, and durable powder-coated steel surface shaders.": "重载工业级五金安装系统商业视觉表现。精细剖析高精度机械铰接转轴、锁紧轴套机构、内部隐藏走线槽以及耐磨粉末喷涂工业钢材真实材质。",
    "Precision hard-surface 3D modeling and turntable animation showcase of a sleek modern cylinder smart speaker. Demonstrates procedural micro-hole perforated acoustic grilles, capacitive top control rings, and smooth cinematic 360-degree orbital camera motion.": "圆柱形现代智能音箱超精硬表面建模与环绕旋转动画。展示程序化微孔声学网罩阵列、顶部电容式触控发光环以及丝滑流畅的360度电影轨道运镜。",
    "Full commercial CGI product animation featuring procedural condensation water droplets, can tab mechanics, embossed aluminum displacement, and explosive cinematic smoke and rim lighting calibrated for commercial advertising.": "全流程商业CGI产品影视广告动画，具备程序化微观水珠凝结模拟、易拉罐拉环机械联动、浮雕铝壳置换贴图以及专为商业电视广告打造的震撼烟雾边缘光效。",
    "Complete real-time asset pipeline demonstrating sub-5MB GLB models, baked PBR textures (Albedo, Roughness, Metalness, Normal, AO), and seamless WebXR compatibility for iOS QuickLook and Android Scene Viewer.": "全栈轻量级实时渲染资产流程，展示单体小于5MB的极致GLB模型、完整烘焙PBR贴图通道，以及无缝兼容iOS QuickLook和Android Scene Viewer的原生WebXR交互体验。",
    "Flagship seating collection featuring compound curve subdivision modeling, realistic micro-fiber bouclé fabric shaders, procedural wood grain joinery, and clean quad topology passes across Capotoni, Caledonian, Finn, and Oculus lounge chairs.": "旗舰级高端座椅设计系列，涵盖复杂复合双曲面细分建模、超写实超细纤维圈圈纱布料材质着色器、程序化木纹榫接结构，以及覆盖Capotoni、Caledonian、Finn与Oculus系列的纯四边形拓扑。",
    "Production game asset workflow: high-poly to low-poly baking, hand-crafted normal decals, edge wear masks, and modular texture reuse calibrated for modern real-time game engines.": "次世代游戏资产生产标准全流程：高模到低模法线高光烘焙、手工细节法线贴花、边缘破损掉漆着色遮罩，以及专为现代次世代游戏引擎校准的模块化材质复用体系。",
    "Photorealistic period prop visualization. Features multi-layered roughness variation, peeling enamel paint, rust and dirt accumulation in crevices, and physical light transmission through an imperfect cylindrical glass mantle.": "超写实历史道具电影级渲染。具备多层微观粗糙度变化、斑驳脱落珐琅烤漆、缝隙泥土与锈迹风化沉淀，以及穿透不规则圆柱形老旧玻璃灯罩的物理真实透光散射。",
    "Hyper-detailed weapons modeling capturing genuine Japanese swordsmithing methods. Features differential hardening blade line (Hamon), intricate cord tsuka-ito wrap over stingray skin, and aged patina metalwork.": "极致考究的冷兵器3D建模，严格遵循正统传统日本锻刀古法。逼真刻画刃区差异热处理刃文（Hamon）、手柄珍珠鱼皮上的复杂十字缠绳（柄卷），以及岁月氧化古铜配件。",
    "Sophisticated bedroom furniture visualization displaying cloth simulation draping, wrinkled linen sheets, velvet upholstered vertical channels, and warm layered ambient lighting across the Royal and Metal bed collections.": "高端寝具家居空间视觉呈现，精彩呈现布料动力学解算垂褶、微褶皱纯棉亚麻床单、立体垂直凹槽丝绒软包床头屏，以及覆盖皇家系列与金属框架床的温润多层次氛围布光。",
    "Carefully crafted hardwood living furniture emphasizing traditional joinery craftsmanship, continuous wood grain orientation along organic edges, and natural diffused sunlight illumination across the Vintage Coffee Table and TV Stand.": "精雕细琢的高档实木客厅家具，着重展现传统榫卯木作工艺美感、沿有机曲面边缘自然延展的连续木质纹理，以及洒落于复古茶几与电视柜上的自然漫射日光。",
    "High-performance real-time environment asset pack engineered for DCS World and military simulation engines. Features strictly controlled draw-calls, shared texture atlases, multiple LOD stages, and optimized collision meshes.": "专为DCS World飞行模拟与现代军工仿真引擎打造的高性能实时环境资产包。具备严格优化的Draw Call渲染调用、全局共享材质图集、多级LOD细节层次以及极简高效碰撞检测网格。",
