// Pre-compute lowercase lookup tables for fast case-insensitive matching
const LOWER_CASE_DICTS = {};
for (const [lang, dict] of Object.entries(SITE_TRANSLATIONS)) {
  LOWER_CASE_DICTS[lang] = {};
  for (const [key, val] of Object.entries(dict)) {
    LOWER_CASE_DICTS[lang][key.trim().toLowerCase()] = val;
  }
}

/**
 * Helper function to translate any text string into active language
 */
function getTranslation(text, langKey) {
  if (!text) return '';
  const lang = (langKey || document.documentElement.lang || 'en').toLowerCase();
  if (lang === 'en' || !SITE_TRANSLATIONS[lang]) return text;
  const trimmed = String(text).trim();
  const dict = SITE_TRANSLATIONS[lang];
  if (dict[trimmed]) return dict[trimmed];
  const clean = trimmed.replace(/\s+/g, ' ');
  if (dict[clean]) return dict[clean];
  const lowerDict = LOWER_CASE_DICTS[lang];
  if (lowerDict && lowerDict[clean.toLowerCase()]) return lowerDict[clean.toLowerCase()];
  return text;
}

/**
 * Traverses visible text nodes and attributes in the DOM and applies translations
 */
function applySiteLanguage(langKey, savePreference = true) {
  if (!SITE_TRANSLATIONS[langKey]) langKey = 'en';

  if (savePreference) {
    try {
      localStorage.setItem('site_preferred_lang', langKey);
    } catch (e) {}
  }

  const isEn = langKey === 'en';
  const isRtl = langKey === 'ar';

  // 1. Toggle RTL / LTR layout and lang tag
  document.documentElement.setAttribute('dir', isRtl ? 'rtl' : 'ltr');
  document.documentElement.setAttribute('lang', langKey);

  // 2. Update navbar language code display
  const currentCodeEl = document.getElementById('langCurrentCode');
  if (currentCodeEl) {
    currentCodeEl.textContent = langKey.toUpperCase();
  }

  // 3. Highlight selected language option
  const langOptions = document.querySelectorAll('.lang-option-item');
  langOptions.forEach(opt => {
    const isSelected = opt.getAttribute('data-lang') === langKey;
    opt.classList.toggle('active', isSelected);
    opt.setAttribute('aria-selected', isSelected ? 'true' : 'false');
  });

  const dict = SITE_TRANSLATIONS[langKey] || SITE_TRANSLATIONS['en'];
  const dictLower = LOWER_CASE_DICTS[langKey] || LOWER_CASE_DICTS['en'];

  // 4. Recursive TreeWalker for all visible text nodes
  const walker = document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: function(node) {
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName.toLowerCase();
        if (tag === 'script' || tag === 'style' || tag === 'noscript' || tag === 'textarea') {
          return NodeFilter.FILTER_REJECT;
        }
        // Avoid touching the language dropdown itself
        if (parent.closest('#langDropdownMenu') || parent.closest('#langToggleBtn')) {
          return NodeFilter.FILTER_REJECT;
        }
        const val = node.nodeValue.trim();
        if (!val) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    }
  );

  const textNodes = [];
  while (walker.nextNode()) {
    textNodes.push(walker.currentNode);
  }

  textNodes.forEach(node => {
    // Cache original English text on the text node itself
    if (typeof node._i18nOrig === 'undefined') {
      node._i18nOrig = node.nodeValue;
    }

    if (isEn) {
      if (node.nodeValue !== node._i18nOrig) {
        node.nodeValue = node._i18nOrig;
      }
      return;
    }

    const origTrim = node._i18nOrig.trim();
    if (!origTrim) return;

    const cleanOrig = origTrim.replace(/\s+/g, ' ');
    const leadingWs = node._i18nOrig.match(/^\s*/)[0];
    const trailingWs = node._i18nOrig.match(/\s*$/)[0];

    // Look up exact or case-insensitive translation
    const translated = dict[cleanOrig] || dictLower[cleanOrig.toLowerCase()];
    if (translated) {
      node.nodeValue = leadingWs + translated + trailingWs;
    } else {
      // Revert to original English if no translation found
      node.nodeValue = node._i18nOrig;
    }
  });

  // 5. Translate Attributes: placeholder
  document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(el => {
    if (typeof el._i18nOrig_ph === 'undefined') {
      el._i18nOrig_ph = el.getAttribute('placeholder') || '';
    }
    const clean = el._i18nOrig_ph.trim().replace(/\s+/g, ' ');
    if (isEn) {
      el.setAttribute('placeholder', el._i18nOrig_ph);
    } else {
      const trans = dict[clean] || dictLower[clean.toLowerCase()];
      if (trans) el.setAttribute('placeholder', trans);
      else el.setAttribute('placeholder', el._i18nOrig_ph);
    }
  });

  // 6. Translate Attributes: title
  document.querySelectorAll('[title]').forEach(el => {
    if (el.closest('#langDropdownMenu') || el.closest('#langToggleBtn')) return;
    if (typeof el._i18nOrig_title === 'undefined') {
      el._i18nOrig_title = el.getAttribute('title') || '';
    }
    const clean = el._i18nOrig_title.trim().replace(/\s+/g, ' ');
    if (isEn) {
      el.setAttribute('title', el._i18nOrig_title);
    } else {
      const trans = dict[clean] || dictLower[clean.toLowerCase()];
      if (trans) el.setAttribute('title', trans);
      else el.setAttribute('title', el._i18nOrig_title);
    }
  });

  // 7. Translate Attributes: aria-label
  document.querySelectorAll('[aria-label]').forEach(el => {
    if (el.closest('#langDropdownMenu') || el.closest('#langToggleBtn')) return;
    if (typeof el._i18nOrig_aria === 'undefined') {
      el._i18nOrig_aria = el.getAttribute('aria-label') || '';
    }
    const clean = el._i18nOrig_aria.trim().replace(/\s+/g, ' ');
    if (isEn) {
      el.setAttribute('aria-label', el._i18nOrig_aria);
    } else {
      const trans = dict[clean] || dictLower[clean.toLowerCase()];
      if (trans) el.setAttribute('aria-label', trans);
      else el.setAttribute('aria-label', el._i18nOrig_aria);
    }
  });

  // 8. Explicit data-i18n elements
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (typeof el._i18nOrig_data === 'undefined') {
      el._i18nOrig_data = el.textContent.trim();
    }
    if (isEn) {
      el.textContent = el._i18nOrig_data;
    } else {
      const trans = dict[key] || dictLower[key.toLowerCase()];
      if (trans) el.textContent = trans;
      else el.textContent = el._i18nOrig_data;
    }
  });

  // 9. Dispatch custom event for dynamic components (portfolio cards, modals, sliders)
  window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang: langKey } }));
}

/**
 * Re-applies active language to dynamically rendered DOM elements
 */
function reapplyLanguage() {
  const currentLang = localStorage.getItem('site_preferred_lang') || 'en';
  applySiteLanguage(currentLang, false);
}

// Global exports
window.applySiteLanguage = applySiteLanguage;
window.reapplyLanguage = reapplyLanguage;
window.getTranslation = getTranslation;
window.SITE_TRANSLATIONS = SITE_TRANSLATIONS;
window.LOWER_CASE_DICTS = LOWER_CASE_DICTS;
